// Shared constants and test matrix for all benchmarks.
// Evdev keycodes used across benchmarks (all backends add +8 for XKB keycodes).

// ── Precompiled RON layout loading (the "no XKB" construction path) ─────
/// Directory holding precompiled layout files (generated by `gen_layouts`).
pub const RON_LAYOUTS_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/ron_layouts");

/// Path to the precompiled RON layout for `(locale, variant)`, e.g. `us.ron`
/// or `us.intl.ron`.
pub fn ron_layout_path(locale: &str, variant: Option<&str>) -> String {
    match variant {
        Some(v) => format!("{RON_LAYOUTS_DIR}/{locale}.{v}.ron"),
        None => format!("{RON_LAYOUTS_DIR}/{locale}.ron"),
    }
}

/// Load one precompiled layout file.
pub fn load_layout_file(locale: &str, variant: Option<&str>) -> wkb::ir::LayoutFile {
    let path = ron_layout_path(locale, variant);
    let text = std::fs::read_to_string(&path).expect("read ron layout file");
    wkb::ir::LayoutFile::from_ron_str(&text).expect("parse ron layout file")
}

/// Ensure the precompiled RON layout for `(locale, variant)` exists,
/// generating it from the XKB registry if missing.
///
/// `ron_layouts/` is a gitignored generated-artifact directory, so a fresh
/// checkout has no files. Generation is a one-time cost outside any timed
/// measurement (call it before registering/starting the benchmarks).
pub fn ensure_layout_file(locale: &str, variant: Option<&str>) {
    let path = ron_layout_path(locale, variant);
    if std::path::Path::new(&path).exists() {
        return;
    }
    std::fs::create_dir_all(RON_LAYOUTS_DIR).expect("create ron layout dir");
    let wkb = wkb::WKB::new_from_names("", "", locale, variant.unwrap_or(""), None)
        .expect("compile layout for fixture");
    let file = wkb.export_layout(0).expect("export layout fixture");
    let ron = file.to_ron_string().expect("serialize layout fixture");
    std::fs::write(&path, ron).expect("write ron layout fixture");
}
